-- cardak_projects.lua — per-window color scheme from the active pane's cwd (theme option A).
-- In M3 this file is generated by `cardak themes apply` from ~/.config/cardak/projects.toml.
--
-- Usage from wezterm.lua:
--   local config = wezterm.config_builder()
--   require('cardak_projects').apply(config)

local wezterm = require 'wezterm'
local home = wezterm.home_dir

local M = {}

-- Longest matching path prefix wins.
M.projects = {
  { name = 'cardak',   path = home .. '/repos/cardak',   scheme = 'Catppuccin Mocha',    accent = '#cba6f7' },
  { name = 'webshop',  path = home .. '/repos/webshop',  scheme = 'Gruvbox Dark (Gogh)', accent = '#fabd2f' },
}

local function cwd_path(pane)
  local cwd = pane:get_current_working_dir()
  if not cwd then return nil end
  if type(cwd) == 'userdata' then return cwd.file_path end -- Url object (20230712+)
  return (tostring(cwd):gsub('^file://[^/]*', ''))         -- older versions: string
end

function M.project_for(path)
  if not path then return nil end
  local best
  for _, p in ipairs(M.projects) do
    if (path == p.path or path:sub(1, #p.path + 1) == p.path .. '/')
        and (not best or #p.path > #best.path) then
      best = p
    end
  end
  return best
end

local function sync_window(window, pane)
  local project = M.project_for(cwd_path(pane))
  local scheme = project and project.scheme or nil -- nil: fall back to config.color_scheme
  local overrides = window:get_config_overrides() or {}
  if overrides.color_scheme ~= scheme then
    overrides.color_scheme = scheme
    window:set_config_overrides(overrides)
    wezterm.log_info(string.format('cardak: window %d -> %s', window:window_id(), tostring(scheme)))
  end
end

function M.apply(config)
  -- update-status fires on focus/tab changes and every status_update_interval (default 1s),
  -- so cd-ing into another project re-themes the window within a second.
  wezterm.on('update-status', sync_window)
  -- Focus request from the deck: it writes OSC 1337 SetUserVar=cardak_focus=<nonce>
  -- to the pane's tty; we activate the pane and ask the WM to raise its window.
  wezterm.on('user-var-changed', function(window, pane, name, value)
    if name ~= 'cardak_focus' then return end
    pane:activate()
    window:focus()
    wezterm.log_info(string.format('cardak: focus pane %d (%s)', pane:pane_id(), value))
  end)
  return config
end

return M
